  fasih_rejected_kabupaten = VALUES(fasih_rejected_kabupaten),
  fasih_approved_provinsi = VALUES(fasih_approved_provinsi),
  fasih_rejected_provinsi = VALUES(fasih_rejected_provinsi),
  fasih_approved_pusat = VALUES(fasih_approved_pusat),
  fasih_rejected_pusat = VALUES(fasih_rejected_pusat),
  fasih_edited_admin = VALUES(fasih_edited_admin),
  fasih_completed_admin = VALUES(fasih_completed_admin),
  fasih_total = VALUES(fasih_total),
  fasih_synced_at = VALUES(fasih_synced_at),
  updated_at = VALUES(updated_at);

-- Sinkronkan target lokal dengan total assignment FASIH
UPDATE sls s
JOIN progress p ON p.sls_id = s.id
SET s.target = p.fasih_total
WHERE p.fasih_synced_at = '2026-08-20 14:24:32' AND p.fasih_total > 0;

-- Non SLS override (area kosong dianggap minimal 1 approved)
UPDATE progress p
JOIN sls s ON s.id = p.sls_id
SET p.fasih_approved_pengawas = LEAST(GREATEST(p.fasih_approved_pengawas, 1), p.fasih_total),
    p.jumlah_submit           = LEAST(GREATEST(p.jumlah_submit, LEAST(GREATEST(p.fasih_approved_pengawas, 1), p.fasih_total)), p.fasih_total)
WHERE CAST(SUBSTRING(s.kode_sls, 11, 4) AS UNSIGNED) >= 1000
  AND p.fasih_total > 0;

-- Snapshot tren hari ini (progress_trend) dari progress yang baru diupdate
-- di atas. captureDailyProgressTrendSnapshot() di Go (progress_trend.go)
-- skip kalau baris hari ini SUDAH ada (mis. sudah kepanggil jam 07:00 WITA
-- pakai data lama sebelum sync ini masuk) -- makanya di sini pakai upsert
-- eksplisit biar snapshot hari ini ketimpa dengan angka yang benar.
INSERT INTO progress_trend (entity_type, entity_id, tanggal, jumlah_submit, jumlah_draft, approved, rejected, revoked)
SELECT 'ppl', s.ppl_id, '2026-08-20',
       COALESCE(SUM(p.jumlah_submit),0), COALESCE(SUM(p.jumlah_draft),0),
       COALESCE(SUM(p.fasih_approved_pengawas),0),
       COALESCE(SUM(p.fasih_rejected_pengawas),0),
       COALESCE(SUM(p.fasih_revoked_pengawas),0)
FROM sls s
LEFT JOIN progress p ON p.sls_id = s.id
GROUP BY s.ppl_id
ON DUPLICATE KEY UPDATE
  jumlah_submit = VALUES(jumlah_submit),
  jumlah_draft  = VALUES(jumlah_draft),
  approved      = VALUES(approved),
  rejected      = VALUES(rejected),
  revoked       = VALUES(revoked);

INSERT INTO progress_trend (entity_type, entity_id, tanggal, jumlah_submit, jumlah_draft, approved, rejected, revoked)
SELECT 'pml', s.pml_id, '2026-08-20',
       COALESCE(SUM(p.jumlah_submit),0), COALESCE(SUM(p.jumlah_draft),0),
       COALESCE(SUM(p.fasih_approved_pengawas),0),
       COALESCE(SUM(p.fasih_rejected_pengawas),0),
       COALESCE(SUM(p.fasih_revoked_pengawas),0)
FROM sls s
LEFT JOIN progress p ON p.sls_id = s.id
GROUP BY s.pml_id
ON DUPLICATE KEY UPDATE
  jumlah_submit = VALUES(jumlah_submit),
  jumlah_draft  = VALUES(jumlah_draft),
  approved      = VALUES(approved),
  rejected      = VALUES(rejected),
  revoked       = VALUES(revoked);

COMMIT;